static int go_stdlib_var_compare(const void *key, const void *row) {
    return strcmp(key, ((const struct go_stdlib_var *)row)->qualified_name);
}

const CBMType *cbm_go_stdlib_variable_type(const char *qualified_name) {
    const struct go_stdlib_var *row = bsearch(qualified_name, go_stdlib_vars,
        sizeof(go_stdlib_vars) / sizeof(go_stdlib_vars[0]), sizeof(go_stdlib_vars[0]),
        go_stdlib_var_compare);
    return row ? row->type : NULL;
}

void cbm_go_stdlib_register(CBMTypeRegistry* reg, CBMArena* arena) {
    (void)arena;
    for (size_t i = 0; i < sizeof(go_stdlib_decl_types) / sizeof(go_stdlib_decl_types[0]); i++)
        cbm_registry_add_type(reg, go_stdlib_decl_types[i]);
    for (size_t i = 0; i < sizeof(go_stdlib_decl_funcs) / sizeof(go_stdlib_decl_funcs[0]); i++)
        cbm_registry_add_func(reg, go_stdlib_decl_funcs[i]);
}
